const byName = new Map();
for (const o of allopt) {
    byName.set(o.name.toLowerCase(), o);
    if (o.alias) byName.set(o.alias.toLowerCase(), o);
}

export function findOption(name) {
    return byName.get(String(name).toLowerCase()) || null;
}
